<?php
[$where,$args]=stockExitFilters($rangeFrom,$rangeTo);
$number=max(1,min(10000,(int)($_GET['p']??1)));$offset=($number-1)*50;$count=(int)query("SELECT COUNT(*) FROM stock_exits e WHERE $where",$args)->fetchColumn();
$rows=query("SELECT e.*,u.name operator_name FROM stock_exits e JOIN users u ON u.id=e.user_id WHERE $where ORDER BY e.id DESC LIMIT 50 OFFSET $offset",$args)->fetchAll();
$detail=empty($_GET['id'])?null:query('SELECT e.*,u.name operator_name FROM stock_exits e JOIN users u ON u.id=e.user_id WHERE e.id=?',[(int)$_GET['id']])->fetch();
if($detail&&!can('inventory')&&$detail['reason']!=='personal_sale'){http_response_code(403);exit('Nemate pristup ovom izlazu.');}
?>
<div class="page-title"><div><p class="eyebrow">IZLAZI IZVAN WEB NARUDŽBI</p><h1>Drugi izlazi robe</h1><p>Povlačenje, otpis, lična prodaja i ostali izlazi imaju vlastiti dokument i obrazloženje.</p></div><div class="action-group"><?php if(can('inventory')):?><a class="btn" href="?page=exits&create=1#exit-editor">＋ Novi izlaz robe</a><?php endif;?><a class="btn secondary" href="?<?=e(http_build_query(array_merge($_GET,['page'=>'exits','export'=>'csv'])))?>">Izvoz CSV ↗</a></div></div>
<nav class="workflow-tabs"><?php foreach([''=>'Svi izlazi']+exitReasons() as $value=>$label):if(!can('inventory')&&$value!==''&&$value!=='personal_sale')continue;?><a class="<?=($_GET['reason']??'')===$value?'active':''?>" href="?page=exits&reason=<?=$value?>"><?=$label?></a><?php endforeach;?></nav>
<?php if(can('inventory')&&(isset($_GET['create'])||($error&&($_POST['action']??'')==='stock_exit'))):?><section id="exit-editor" class="panel editor-panel"><h2>Novi dokument izlaza</h2><?php startForm('stock_exit');?><input type="hidden" name="exit_token" value="<?=e($_SESSION['stock_exit_token'])?>"><div class="editor-grid"><div><?php $opts=[];foreach(query('SELECT id,sku,name,stock,reserved FROM products ORDER BY name')->fetchAll() as $p)$opts[$p['id']]=$p['sku'].' · '.$p['name'].' ('.$p['stock'].' slobodno, '.$p['reserved'].' rezervisano)';selectField('product_id','Artikal',$opts,$_POST['product_id']??'');field('quantity','Broj komada',$_POST['quantity']??1,'number');selectField('reason','Vrsta izlaza',exitReasons(),$_POST['reason']??'write_off');field('document_ref','Broj dokumenta / odluke / potvrde',$_POST['document_ref']??'','text',false);textField('exit_note','Obavezno obrazloženje',$_POST['exit_note']??'');?></div><div><fieldset class="publication-options" data-personal-sale-fields><legend>Samo za ličnu prodaju</legend><?php field('recipient','Kupac / primalac',$_POST['recipient']??'','text',false);field('unit_price','Prodajna cijena po komadu KM',$_POST['unit_price']??'0.00','text',false);selectField('exit_payment','Naplata',['unpaid'=>'Čeka naplatu']+(can('payments')?['paid'=>'Naplaćeno pri predaji']:[]),$_POST['exit_payment']??'unpaid');?><p class="field-help">Kod lične prodaje količina izlazi odmah. Naplatu može potvrditi samo ovlašteni korisnik za naplatu. Povlačenje, otpis i drugi izlaz nemaju status naplate.</p></fieldset><div class="notice warning">Ovaj obrazac umanjuje samo slobodan lager. Za rezervisanu robu iz web narudžbe koristite obradu te narudžbe; ne evidentirajte istu predaju dvaput.</div></div></div><div class="form-footer"><button>Potvrdi izlaz i razduži lager</button><a href="?page=exits">Odustani</a></div></form></section><?php endif;?>
<?php if($detail):?><section class="panel"><div class="section-heading"><div><h2>Dokument izlaza #<?=$detail['id']?></h2><p><?=e(exitReasons()[$detail['reason']]??$detail['reason'])?> · <?=e($detail['created_at'])?> · <?=e($detail['operator_name'])?></p></div><span class="status-badge <?=$detail['reversed_at']?'status-returned':'status-shipped'?>"><?=$detail['reversed_at']?'Stornirano i vraćeno na lager':'Razduženo s lagera'?></span></div><div class="admin-columns"><div><h3><?=e($detail['product_name'])?></h3><p><?=e($detail['sku'])?> · <?=$detail['quantity']?> kom.</p><p>Dokument: <?=e($detail['document_ref']?:'Nije naveden')?><br>Primalac: <?=e($detail['recipient']?:'—')?></p><p><?=nl2br(e($detail['note']))?></p><?php if($detail['reason']==='personal_sale'):?><p>Prodajni iznos: <strong><?=money((float)$detail['total'])?></strong> · <span class="status-badge status-<?=e($detail['payment_status'])?>"><?=e(paymentLabel($detail['payment_status']))?></span></p><?php endif;if($detail['reversed_at']):?><p>Storno: <?=e($detail['reversed_at'])?><br><?=nl2br(e((string)$detail['reversal_note']))?></p><?php endif;?></div><div><?php if($detail['reason']==='personal_sale'&&can('payments')&&!$detail['reversed_at']):?><h3>Naplata lične prodaje</h3><?php startForm('exit_payment',(int)$detail['id']);selectField('payment_status','Radnja',$detail['payment_status']==='paid'?['refunded'=>'Povrat novca']:['paid'=>'Naplaćeno']);textField('exit_note','Dokument / obrazloženje naplate');?><button>Potvrdi finansijsku radnju</button></form><?php endif;if(can('inventory')&&!$detail['reversed_at']):?><details class="secondary-operation"><summary>Storniraj dokument i vrati robu na lager</summary><p class="field-help">Original se ne briše. Naplaćena lična prodaja prvo traži povrat novca. Ne koristite storno ako roba nije vraćena ili je izlaz stvarno izvršen.</p><?php startForm('exit_reverse',(int)$detail['id']);textField('exit_note','Obavezno obrazloženje storna / vraćanja robe');?><button>Potvrdi storno i povrat količine</button></form></details><?php endif;?></div></div><h3>Historija dokumenta</h3><div class="table-scroll"><table><thead><tr><th>Datum</th><th>Radnja</th><th>Obrazloženje</th><th>Operater</th></tr></thead><tbody><?php foreach(query("SELECT a.*,u.name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE a.entity_id=? AND a.action LIKE 'stock_exit.%' ORDER BY a.id DESC",[$detail['id']])->fetchAll() as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e(activityLabel($a['action']))?></td><td><?=e(activityDetails($a))?></td><td><?=e($a['name']??'Sistem')?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<section class="panel"><form method="get" class="admin-filters"><input type="hidden" name="page" value="exits"><div><?php field('q','Broj, artikal, SKU, primalac, dokument ili obrazloženje',$_GET['q']??'','text',false);?></div><div><?php selectField('reason','Vrsta',[''=>'Sve vrste']+exitReasons(),$_GET['reason']??'');?></div><div><?php selectField('payment','Naplata',[''=>'Sva stanja','not_applicable'=>'Bez naplate','unpaid'=>'Nenaplaćeno','paid'=>'Naplaćeno','refunded'=>'Vraćen novac'],$_GET['payment']??'');?></div><div><?php selectField('state','Dokument',[''=>'Svi','active'=>'Važeći izlaz','reversed'=>'Stornirano'],$_GET['state']??'');?></div><div><?php field('from','Datum od',$rangeFrom,'date',false);?></div><div><?php field('to','Datum do',$rangeTo,'date',false);?></div><div><?php $operators=[''=>'Svi operateri'];foreach(query('SELECT id,name FROM users ORDER BY name')->fetchAll() as $urow)$operators[$urow['id']]=$urow['name'];selectField('operator','Operater',$operators,$_GET['operator']??'');?></div><button>Primijeni filter</button></form><div class="table-heading"><h2>Registar drugih izlaza</h2><span><?=$count?> rezultata</span></div><div class="table-scroll"><table><thead><tr><th>Dokument / datum</th><th>Artikal</th><th>Vrsta</th><th>Količina</th><th>Primalac / obrazloženje</th><th>Naplata</th><th>Operater</th><th>Stanje</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a href="?page=exits&id=<?=$row['id']?>">#<?=$row['id']?> · <?=e($row['document_ref'])?></a><small class="cell-note"><?=e($row['created_at'])?></small></td><td><?=e($row['product_name'])?><small class="cell-note"><?=e($row['sku'])?></small></td><td><?=e(exitReasons()[$row['reason']]??$row['reason'])?></td><td><?=$row['quantity']?></td><td><?=e($row['recipient'])?><small class="cell-note"><?=e($row['note'])?></small></td><td><?php if($row['reason']==='personal_sale'):?><?=money((float)$row['total'])?><small class="cell-note"><?=e(paymentLabel($row['payment_status']))?></small><?php else:?>Nije primjenjivo<?php endif;?></td><td><?=e($row['operator_name'])?></td><td><span class="status-badge <?=$row['reversed_at']?'status-returned':'status-shipped'?>"><?=$row['reversed_at']?'Stornirano':'Razduženo'?></span></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="table-empty">Nema izlaza za odabrane filtere.</td></tr><?php endif;?></tbody></table></div><div class="list-pagination"><span>Stranica <?=$number?> / <?=max(1,(int)ceil($count/50))?></span><?php foreach([-1=>'← Prethodna',1=>'Sljedeća →'] as $delta=>$label):if(($delta<0&&$number>1)||($delta>0&&$offset+50<$count)):?><a href="?<?=e(http_build_query(array_merge($_GET,['p'=>$number+$delta])))?>"><?=$label?></a><?php endif;endforeach;?></div></section>
